*/
scwin.__on_enter_2_ipt_corpName = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_2_ipt_corpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.searchCorpList() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00140.__on_enter_2_ipt_corpName' }); }
};

/**
 * @method
 * @name scwin.searchCorpList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCorpList = async function () {
    /* sdd-asis-lifecycle:begin searchCorpList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.clearBtnImage();
    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "");
    (document.corpListForm || { elements: [] }).target = "iframe";
    (document.corpListForm || { elements: [] }).action = "/submission/etnLpList.do?method=searchEtnLp";
    await scwin.tx_searchCorpList();
    /* sdd-asis-lifecycle:end */
};


