    (document.corpListForm || { elements: [] }).target = "iframe";
    (document.corpListForm || { elements: [] }).action = "/submission/etnLpList.do?method=searchEtnLp";
    await scwin.tx_searchCorpListByBeginIndex();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.swapImage
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj no
 * @returns
 * @hidden N
*/
scwin.swapImage = function (obj, no) {
    /* sdd-asis-lifecycle:begin swapImage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchCorpListReq').set('pageIndex', 1);
    scwin.clearBtnImage();
    const frm = (document.corpListForm || { elements: [] });
    obj.setSrc("/img/submission/corpfind/btn_initial" + no + "_on.gif");
    if (no === "01") {
        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "A");
    } else {
        if (no === "02") {
            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "B");
        } else {
            if (no === "03") {
                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "C");
            } else {
                if (no === "04") {
                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "D");
                } else {
                    if (no === "05") {
                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "E");
                    } else {
                        if (no === "06") {
                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "F");
                        } else {
                            if (no === "07") {
                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "G");
                            } else {
                                if (no === "08") {
                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "H");
                                } else {
                                    if (no === "09") {
                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "I");
                                    } else {
                                        if (no === "10") {
                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "J");
                                        } else {
                                            if (no === "11") {
                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "K");
                                            } else {
                                                if (no === "12") {
                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "L");
                                                } else {
                                                    if (no === "13") {
                                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "M");
                                                    } else {
                                                        if (no === "14") {
                                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "N");
                                                        } else {
                                                            if (no === "18") {
                                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "AZ");
                                                            } else {
                                                                if (no === "17") {
                                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "ETC");
                                                                }
                                                            }
